// src/lib/dal.ts
export const verifySession = cache(async (): Promise<Session> => {
  const cookieStore = await cookies();
  const authCookie = cookieStore.get(AUTH_COOKIE);

  if (!authCookie?.value) {
    throw new AppError("UNAUTHORIZED", "Authentication required");
  }

  const session = validateToken(authCookie.value, getSecret());
  if (!session) {
    throw new AppError("UNAUTHORIZED", "Invalid or expired token");
  }

  return session;
});
```

**Explanation:** This function retrieves the `AUTH_COOKIE` from the cookie store. If the cookie is missing or its value is empty, it throws an `AppError` indicating "Authentication required". It then validates the token within the cookie using `validateToken()` and `getSecret()`. If the token is invalid or expired, it throws an "Invalid or expired token" error. Otherwise, it returns the `Session` object containing `ownerid` and `isAdmin` information.

