import { NextRequest, NextResponse } from "next/server";
import { startServerGracefully } from "express";
import { getMetric } from "@/lib/metrics"; // Assuming a Prometheus client or similar is used

export function apiMetricsMiddleware(handler: NextApiHandler) {
  return async (req: NextRequest, res: NextResponse) => {
    const startTimestamp = Date.now();

    const response = await handler(req, res);

    const latency = Date.now() - startTimestamp;
    const metric = getMetric("api_request_latency_seconds");
