    async function checkRedisHealth(): Promise<boolean> {
      if (!env.UPSTASH_REDIS_REST_URL || !env.UPSTASH_REDIS_REST_TOKEN) {
        return false;
      }
      const redis = new Redis({
        url: env.UPSTASH_REDIS_REST_URL,
        token: env.UPSTASH_REDIS_REST_TOKEN,
      });
      const ping = await redis.ping().catch(() => false);
      return ping === "PONG";
    }

    export function createRateLimiter(config: RateLimitConfig) {
      if (!env.UPSTASH_REDIS_REST_URL || !env.UPSTASH_REDIS_REST_TOKEN) {
        console.warn("Redis rate limiter disabled: UPSTASH_REDIS_REST_URL or UPSTASH_REDIS_REST_TOKEN not configured.");
        return null;
      }

      const redis = new Redis({
        url: env.UPSTASH_REDIS_REST_URL,
        token: env.UPSTASH_REDIS_REST_TOKEN,
      });

      // Attempt a basic Redis operation with a timeout to check for availability
      const isRedisAvailable = await checkRedisHealth();
      if (!isRedisAvailable) {
        console.warn("Redis rate limiter disabled: Redis service is unreachable.");
        return null;
      }

      return new Ratelimit({
        redis,
        limiter: Ratelimit.slidingWindow(config.limit, config.window as Parameters<typeof Ratelimit.slidingWindow>[1]),
        prefix: config.prefix,
      });
    }
