2.  **Implement In-Memory Rate Limiter:** Create a new file, `src/lib/fallback-rate-limit.ts`, which contains a basic in-memory rate limiter. This limiter will use a fixed window (e.g., 60 seconds) and a configurable maximum number of requests per window. It will be used only when Redis is unavailable.

    *   **File:** `src/lib/fallback-rate-limit.ts`
    *   **Lines:** All (new file)


```typescript
    // src/lib/fallback-rate-limit.ts
    import { NextRequest, NextResponse } from "next/server";

    type FallbackRateLimitConfig = {
      prefix: string; // Unique prefix for the endpoint or user
      maxRequests: number; // Maximum number of requests allowed per window
      windowSeconds: number; // Time window in seconds
    };

    // In-memory rate limiter using a fixed window
    export function createFallbackRateLimiter(config: FallbackRateLimitConfig) {
      const { prefix, maxRequests, windowSeconds } = config;
      const rateLimitKey = `fallback:${prefix}`;

      // Store { [ip]: { count: number, windowEnd: number } }
      const rateLimitStore: { [ip: string]: { count: number; windowEnd: number } } = {};

      return (ip: string) => {
        const now = Date.now();

        // Check if the entry for this IP exists and if the window has expired
        if (rateLimitStore[ip] && rateLimitStore[ip].windowEnd < now) {
          rateLimitStore[ip] = { count: 0, windowEnd: now + windowSeconds * 1000 };
        }

        // Update or create the entry
        if (!rateLimitStore[ip]) {
          rateLimitStore[ip] = { count: 0, windowEnd: now + windowSeconds * 1000 };
        }

        rateLimitStore[ip].count += 1;

        // Check if the request exceeds the limit
        if (rateLimitStore[ip].count > maxRequests) {
          console.warn(`Rate limited: ${ip} exceeded ${maxRequests} requests for ${windowSeconds} seconds.`);
          return { success: false, remaining: 0, reset: now + windowSeconds * 1000 };
        }

        return { success: true, remaining: maxRequests - rateLimitStore[ip].count, reset: now + windowSeconds * 1000 };
      };
    }
    ```


